class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.current_frame = 0
        self.is_frame_complete = False
        self.frame_rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError("Invalid number of pins")

        self.rolls.append(pins)
        self.frame_rolls.append(pins)

        # Check if we're at the end of a frame
        if self.is_frame_complete:
            self.current_frame += 1
            self.frame_rolls = [pins]
            self.is_frame_complete = False
        else:
            # Check if this completes the frame
            if len(self.frame_rolls) == 2:
                # Frame is complete (either spare or open)
                self.is_frame_complete = True
            elif len(self.frame_rolls) == 1 and pins == 10:
                # Strike - frame is complete
                self.is_frame_complete = True

    def score(self):
        if len(self.rolls) < 10:
            raise ValueError("Game not complete")

        total_score = 0
        roll_index = 0

        for frame in range(10):
            if roll_index >= len(self.rolls):
                break

            # Check if it's a strike
            if self.rolls[roll_index] == 10:
                # Strike
                total_score += 10
                # Add next two rolls (or as many as available)
                if roll_index + 1 < len(self.rolls):
                    total_score += self.rolls[roll_index + 1]
                if roll_index + 2 < len(self.rolls):
                    total_score += self.rolls[roll_index + 2]
                roll_index += 1
            else:
                # Not a strike - check for spare
                frame_total = self.rolls[roll_index] + self.rolls[roll_index + 1]
                if frame_total == 10:
                    # Spare
                    total_score += 10
                    # Add next roll (if available)
                    if roll_index + 2 < len(self.rolls):
                        total_score += self.rolls[roll_index + 2]
                else:
                    # Open frame
                    total_score += frame_total
                roll_index += 2

        return total_score
```

